import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../../state/auth_state.dart';
import '../../core/app_theme.dart';
import '../../widgets/devhub_widgets.dart';
class SettingsScreen extends StatefulWidget{const SettingsScreen({super.key});@override State<SettingsScreen> createState()=>_SettingsScreenState();}
class _SettingsScreenState extends State<SettingsScreen>{bool busy=false;
 @override Widget build(BuildContext context){final auth=context.watch<AuthState>();final u=auth.user;if(u==null)return const LoadingView();final privacy=u.privacy;return ListView(padding:const EdgeInsets.all(18),children:[Text('Settings',style:Theme.of(context).textTheme.headlineMedium),const SizedBox(height:5),const Text('Manage your profile visibility and account.',style:TextStyle(color:AppColors.muted)),const SizedBox(height:20),Panel(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Profile visibility',style:Theme.of(context).textTheme.titleMedium),SwitchListTile(contentPadding:EdgeInsets.zero,title:const Text('Public profile'),subtitle:const Text('Allow developers to view your profile'),value:privacy['isPublic']!=false,activeThumbColor:AppColors.violet,onChanged:(v)=>_save(auth,{'privacy':{'isPublic':v}})),SwitchListTile(contentPadding:EdgeInsets.zero,title:const Text('Show email'),subtitle:const Text('Display your email on your public profile'),value:privacy['showEmail']==true,activeThumbColor:AppColors.violet,onChanged:(v)=>_save(auth,{'privacy':{'showEmail':v}})),SwitchListTile(contentPadding:EdgeInsets.zero,title:const Text('Show private repositories'),value:privacy['showPrivateRepos']==true,activeThumbColor:AppColors.violet,onChanged:(v)=>_save(auth,{'privacy':{'showPrivateRepos':v}}))])),const SizedBox(height:14),Panel(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Account',style:Theme.of(context).textTheme.titleMedium),const SizedBox(height:8),Text('@${u.username}',style:const TextStyle(color:AppColors.muted)),const SizedBox(height:12),OutlinedButton.icon(onPressed:busy?null:()async{await auth.signOut();if(context.mounted)Navigator.pushNamedAndRemoveUntil(context,'/',(_)=>false);},icon:const Icon(Icons.logout,color:AppColors.red),label:const Text('Sign out'))]))]);}
 Future<void> _save(AuthState auth,Map<String,dynamic> data)async{try{await auth.updateProfile(data);if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Settings saved')));}catch(e){if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}}
}
